I = importlib
__owner = Variable(contract='con_game_manager_v1', name='owner')
__metadata = Hash(default_value=None, contract='con_game_manager_v1', name=
    'metadata')
__contracts_list = Variable(contract='con_game_manager_v1', name=
    'contracts_list')
__actions = Hash(contract='con_game_manager_v1', name='actions')
S = {'metadata': __metadata, 'owner': __owner}
action_interface = [I.Func('interact', args=('payload', 'state', 'caller'))]


def ____():
    __owner.set(ctx.caller)
    __contracts_list.set([])


@__export('con_game_manager_v1')
def register_action(action: str, contract: str):
    assert ctx.caller == __owner.get(), 'Only owner can call!'
    assert __actions[action] is None, 'Action already registered!'
    p = I.import_module(contract)
    assert I.owner_of(p
        ) == ctx.this, 'This contract must control the action contract!'
    assert I.enforce_interface(p, action_interface
        ), 'Action contract does not follow the correct interface!'
    contracts = __contracts_list.get()
    contracts.append(contract)
    __contracts_list.set(contracts)
    __actions[action] = contract


@__export('con_game_manager_v1')
def override_action(action: str, contract: str):
    assert ctx.caller == __owner.get(), 'Only owner can call!'
    original_contract = __actions[action]
    assert original_contract is not None, 'Action not already registered!'
    p = I.import_module(contract)
    assert I.owner_of(p
        ) == ctx.this, 'This contract must control the action contract!'
    assert I.enforce_interface(p, action_interface
        ), 'Action contract does not follow the correct interface!'
    contracts = __contracts_list.get()
    if original_contract in contracts:
        contracts.remove(original_contract)
    contracts.append(contract)
    __contracts_list.set(contracts)
    __actions[action] = contract


@__export('con_game_manager_v1')
def unregister_action(action: str):
    assert ctx.caller == __owner.get(), 'Only owner can call!'
    contract = __actions[action]
    assert contract is not None, 'Action does not exist!'
    contracts = __contracts_list.get()
    if contract in contracts:
        contracts.remove(contract)
    __contracts_list.set(contracts)
    __actions[action] = None


@__export('con_game_manager_v1')
def interact(action: str, payload: dict) ->Any:
    contract = __actions[action]
    assert contract is not None, 'Invalid action!'
    module = I.import_module(contract)
    result = module.interact(payload, S, ctx.caller)
    return result


@__export('con_game_manager_v1')
def bulk_interact(action: str, payloads: list):
    for payload in payloads:
        interact(action, payload)


